import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';

const SRC = 'assets/editor-web/index.html';
const OUT = 'src/generated/editor-html.ts';

const html = readFileSync(SRC, 'utf8');
mkdirSync('src/generated', { recursive: true });
writeFileSync(
  OUT,
  '// AUTO-GENERATED by scripts/generate-editor-html.mjs - do not edit.\n' +
    'export const EDITOR_HTML = ' +
    JSON.stringify(html) +
    ';\n',
);
console.log(`Wrote ${OUT} (${(html.length / 1024 / 1024).toFixed(2)} MB of HTML)`);
